 for(String category:new String[]{"전체","팔","어깨","등","가슴","철봉"}){TextView chip=new TextView(this);chip.setText(category);chip.setTextSize(15);chip.setPadding(dp(14),dp(14),dp(14),dp(14));chip.setTextColor(accent);chips.addView(chip);chip.setOnClickListener(v->query.setText(category.equals("전체")?"":category));}
 query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence t,int st,int c,int a){}public void onTextChanged(CharSequence t,int st,int before,int count){refresh[0].run();}public void afterTextChanged(android.text.Editable t){}});
 refresh[0].run();ScrollView sc=new ScrollView(this);sc.addView(f);AlertDialog picker=new AlertDialog.Builder(this).setView(sc).setPositiveButton("완료",(d,w)->{tab="운동";show();}).create();picker.show();picker.getWindow().setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*.88));picker.setOnDismissListener(d->{tab="운동";show();});
